142|                // Invalid Jalali date string — ignore filter
143|            }
144|        }
145|        if ($this->dateTo) {
146|            try {
147|                $miladiTo = \Morilog\Jalali\Jalalian::fromFormat('Y/m/d', $this->dateTo)->toCarbon()->endOfDay();
148|                $query->where('created_at', '<=', $miladiTo);
