257|    public function executeBulkAction(): void
258|    {
259|        if (empty($this->selectedTickets)) return;
260|
261|        // Issue #818: the bulk `complete` branch closes tickets in bulk, which is
262|        // the same state change the single-ticket path needed
263|        // manage_unit_tickets for. `forward` stays open to the route gate
264|        // because it does not move the ticket out of its unit (its own latent
265|        // issue — see #818 "Out of scope").
