267|            $this->authorize('manage_unit_tickets');
268|        }
269|
270|        $count = count($this->selectedTickets);
271|        $now = now();
272|        $userId = auth()->id();
273|        $bulkNote = $this->bulkNote;
274|
275|        // Get accessible unit IDs for scope filtering
276|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
277|
278|        // ۱. یک کوئری برای همه تیکت‌ها - فیلتر تیکت‌های قبلاً completed شده + محدوده سازمانی
279|        $ticketIds = Ticket::whereIn('id', $this->selectedTickets)
280|            ->where('status', '!=', 'completed')
281|            ->whereIn('unit_id', $accessibleIds)
282|            ->pluck('id');
283|
284|        if ($ticketIds->isEmpty()) {
285|            $this->dispatch('swal', ['title' => 'هیچ تیکت قابل پردازشی یافت نشد', 'icon' => 'warning']);
286|            $this->closeAllModals();
287|            return;
