289|
290|        DB::transaction(function () use ($ticketIds, $count, $now, $userId, $bulkNote) {
291|            // Issue #531: capture old statuses BEFORE the bulk update
292|            $oldStatuses = Ticket::whereIn('id', $ticketIds)
