304|                $cache->increment('gis');
305|                $cache->increment('calendar');
306|                $cache->increment('dashboard');
307|
308|                // ۳. یک batch INSERT برای فعالیت‌ها
309|                $activityRows = $ticketIds->map(fn($id) => [
310|                    'ticket_id' => $id,
311|                    'user_id' => $userId,
312|                    'action' => 'completed',
313|                    'description' => 'تکمیل دسته‌ای تیکت' . ($bulkNote ? ": {$bulkNote}" : ''),
314|                    'created_at' => $now,
315|                    'updated_at' => $now,
316|                ])->toArray();
317|                TaskActivity::insert($activityRows);
318|
319|                // ActivityLogService - با استفاده از وضعیت قبل از آپدیت
320|                $tickets = Ticket::whereIn('id', $ticketIds)->get(['id', 'ticket_code', 'status', 'task_id']);
321|                $completedTaskIds = $tickets->pluck('task_id')->filter()->unique();
322|
323|                foreach ($tickets as $ticket) {
324|                    $oldStatus = $oldStatuses->get($ticket->id, $ticket->status);
325|                    \App\Services\ActivityLogService::updated($ticket, ['status' => $oldStatus], ['status' => 'completed'], "تکمیل دسته‌ای تیکت {$ticket->ticket_code}");
326|                }
327|
328|                // Plan 005: Auto-complete parent tasks where all child tickets are completed
329|                foreach ($completedTaskIds as $taskId) {
330|                    $incompleteCount = Ticket::where('task_id', $taskId)
