341|                    'status' => 'forwarded',
342|                    'current_assignee_id' => null,
343|                ]);
344|                // Issue #378/#389: bulk update bypasses Eloquent events — bump caches manually
345|                $cache = app(CacheInvalidationServiceInterface::class);
346|                $cache->increment('report_tickets');
347|                $cache->increment('gis');
348|                $cache->increment('calendar');
