353|                    'user_id' => $userId,
354|                    'action' => 'forwarded',
355|                    'description' => 'ارجاع دسته‌ای تیکت' . ($bulkNote ? ": {$bulkNote}" : ''),
356|                    'created_at' => $now,
357|                    'updated_at' => $now,
358|                ])->toArray();
359|                TaskActivity::insert($activityRows);
