117|     */
118|    protected function resolveValue(Unit $unit, string $key, array $meta): mixed
119|    {
120|        return match ($key) {
121|            'unit_type' => $unit->unitType->name ?? '-',
122|            'county' => $this->resolveCounty($unit),
123|            'parent_name' => $meta['parent_name'] !== '' ? $meta['parent_name'] : '-',
124|            'full_path' => $meta['path'],
125|            'depth' => $meta['depth'],
