125|                    COUNT(*) FILTER (WHERE is_completed = true) AS completed_todos
126|                FROM todos WHERE unit_id IN ({$idList})
127|            ", $accessibleIds);
128|
129|            // Linked todos (tickets.task_id -> todos.id)
