131|                SELECT COUNT(DISTINCT t.id) AS cnt
132|                FROM todos t
133|                WHERE t.unit_id IN ({$idList})
134|                  AND EXISTS (SELECT 1 FROM tickets WHERE task_id = t.id)
135|            ", $accessibleIds);
