8|use Mary\Traits\Toast;
9|
10|return new class extends Component
11|{
12|    use Toast;
13|
14|    public string $search = '';
15|
16|    public array $expanded = [];
17|
18|    public $rootUnits;
19|
20|    public $selectedUnit = null;
21|
22|    public int $descendantUserCount = 0;
23|
24|    public int $directUserCount = 0;
25|
26|    public function mount(): void
27|    {
28|        $this->loadData();
29|
30|        if (empty($this->expanded)) {
31|            $this->expanded = $this->expandFirstNLevels($this->rootUnits->all(), 3);
32|        }
33|    }
34|
35|    /**
36|     * Livewire restores Eloquent models by key only, so the in-memory
37|     * childrenRecursive tree from buildTree() does not survive toggle().
38|     */
39|    public function hydrate(): void
40|    {
41|        $this->loadData();
42|    }
43|
44|    /**
45|     * Expand root units and their children up to maxLevel.
46|     */
47|    /** @param  Collection<int, Unit>  $nodes  @return  list<string> */
48|    protected function expandFirstNLevels($nodes, int $maxLevel, int $level = 1): array
49|    {
50|        $ids = [];
51|        foreach ($nodes as $node) {
52|            if ($level <= $maxLevel) {
53|                $ids[] = (string) $node->id;
54|            }
55|            if ($level < $maxLevel && $node->childrenRecursive->isNotEmpty()) {
56|                $ids = array_merge($ids, $this->expandFirstNLevels($node->childrenRecursive, $maxLevel, $level + 1));
57|            }
58|        }
59|
60|        return $ids;
61|    }
62|
63|    public function loadData(): void
64|    {
65|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
66|
67|        $rootIds = Unit::whereNull('parent_id')
68|            ->whereIn('id', $accessibleIds)
69|            ->pluck('id')
70|            ->all();
71|
72|        $this->rootUnits = Unit::buildTree($rootIds, $accessibleIds);
73|    }
74|
75|    public function updatedSearch(): void
76|    {
77|        $this->expanded = [];
78|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
79|
80|        if (strlen($this->search) > 2) {
81|            $matchingUnits = Unit::where('name', 'LIKE', "%{$this->search}%")
82|                ->whereIn('id', $accessibleIds)
83|                ->get();
84|
85|            foreach ($matchingUnits as $unit) {
86|                $this->expandParents($unit);
87|            }
88|
89|            $this->expanded = array_unique($this->expanded);
90|        }
91|    }
92|
93|    protected function expandParents($unit): void
94|    {
95|        if ($unit->parent_id) {
96|            $this->expanded[] = (string) $unit->parent_id;
97|            $parent = Unit::find($unit->parent_id);
98|            if ($parent) {
99|                $this->expandParents($parent);
100|            }
101|        }
102|    }
103|
104|    public function toggle($id): void
105|    {
106|        if (in_array($id, $this->expanded)) {
107|            $this->expanded = array_diff($this->expanded, [$id]);
108|        } else {
109|            $this->expanded[] = $id;
110|        }
111|    }
