113|    public function selectUnit(int $id): void
114|    {
115|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
116|
117|        if (! in_array($id, $accessibleIds)) {
118|            $this->error('شما مجاز به مشاهده این واحد نیستید.', position: 'toast-bottom');
119|
120|            return;
121|        }
122|
123|        $this->selectedUnit = Unit::with(['parent', 'unitType', 'assignedUsers.person', 'person'])->find($id);
124|        $descendantIds = Unit::descendantIds($id)->filter(fn ($did) => $did != $id)->values();
125|        $this->descendantUserCount = User::whereHas('units', fn ($q) => $q->whereIn('unit_id', $descendantIds))->count();
126|        $this->directUserCount = $this->selectedUnit->assignedUsers->count();
127|    }
