2|
3|use App\Models\Ticket;
4|use App\Models\Todo;
5|use App\Models\Unit;
6|use App\Services\AccessService;
7|use Livewire\Component;
8|use Livewire\WithPagination;
9|use Livewire\Attributes\Layout;
10|use Livewire\Attributes\Url;
11|use Livewire\Attributes\Computed;
12|use Mary\Traits\Toast;
13|use Illuminate\Support\Facades\Auth;
14|
15|new class extends Component
16|{
17|    use WithPagination;
18|    use Toast;
19|
20|    public bool $showHelpModal = false;
21|
22|    #[Url]
23|    public string $search = '';
24|    #[Url]
25|    public string $statusFilter = 'all';
26|    #[Url]
27|    public ?int $selectedUnitId = null;
28|    #[Url]
29|    public string $unitSearch = '';
30|    #[Url]
31|    public string $dateFrom = '';
32|    #[Url]
33|    public string $dateTo = '';
34|
35|    public bool $showModal = false;
36|    public ?Ticket $showingTicket = null;
37|    public bool $modalDetail = false;
38|
39|    public array $filterUnits = [];
40|    public ?Unit $currentUnit = null;
41|
42|    public function mount(): void
43|    {
44|        $this->loadData();
45|    }
46|
47|    public function updated(string $property): void
48|    {
49|        if (in_array($property, ['search', 'statusFilter', 'selectedUnitId', 'dateFrom', 'dateTo'])) {
50|            $this->resetPage();
51|        }
52|        $this->loadData();
53|    }
54|
55|    public function loadData(): void
56|    {
57|        $units = [];
58|        if (mb_strlen($this->unitSearch) > 1) {
59|            $units = Unit::where('name', 'like', '%' . $this->unitSearch . '%')
60|                ->where('can_receive_tickets', true)
61|                ->limit(10)->get()->toArray();
62|        }
63|        $this->filterUnits = $units;
64|
65|        $this->currentUnit = $this->selectedUnitId ? Unit::find($this->selectedUnitId) : null;
66|    }
67|
68|    #[Computed]
69|    public function tickets()
70|    {
71|        $query = Ticket::with(['user' => fn ($q) => $q->select('id', 'n_code')->with('person:f_name,l_name'), 'unit:id,name'])->accessible();
72|
73|        if ($this->selectedUnitId) {
74|            $query->where('unit_id', $this->selectedUnitId);
75|        }
76|
77|        if ($this->statusFilter === 'pending') {
78|            $query->whereIn('status', ['created', 'forwarded']);
79|        } elseif ($this->statusFilter !== 'all') {
80|            $query->where('status', $this->statusFilter);
81|        }
82|
83|        if (!empty($this->search)) {
84|            $query->where(function ($q) {
85|                $q->where('subject', 'like', '%' . $this->search . '%')
86|                    ->orWhere('ticket_code', 'like', '%' . $this->search . '%');
87|            });
88|        }
89|
90|        if ($this->dateFrom) {
91|            try {
92|                $miladiFrom = \Morilog\Jalali\Jalalian::fromFormat('Y/m/d', $this->dateFrom)->toCarbon()->startOfDay();
93|                $query->where('created_at', '>=', $miladiFrom);
94|            } catch (\Throwable) {
95|                // Invalid Jalali date string — ignore filter
96|            }
97|        }
98|
99|        if ($this->dateTo) {
100|            try {
101|                $miladiTo = \Morilog\Jalali\Jalalian::fromFormat('Y/m/d', $this->dateTo)->toCarbon()->endOfDay();
102|                $query->where('created_at', '<=', $miladiTo);
103|            } catch (\Throwable) {
104|                // Invalid Jalali date string — ignore filter
105|            }
106|        }
107|
108|        return $query->latest()->paginate(20);
109|    }
110|
111|    public function selectUnitForFilter($id): void
112|    {
113|        $this->selectedUnitId = $id;
114|        $this->unitSearch = '';
115|        $this->resetPage();
116|        $this->loadData();
117|    }
118|
119|    public function showTicket($id): void
120|    {
121|        // Check organizational scope
122|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
123|        /** @var Ticket|null $ticket */
124|        $ticket = Ticket::with([
125|            'user',
126|            'unit',
127|            'attachments',
128|            'activities.user',
129|            'activities.attachments'
130|        ])->findOrFail($id);
131|
132|        if (! in_array($ticket->unit_id, $accessibleIds)) {
133|            $this->error('شما مجاز به مشاهده این تیکت نیستید.', position: 'toast-bottom');
134|            return;
135|        }
136|
137|        // #847: same leak as the inbox — the ticket is scoped, the `task`
138|        // relation is not. Gate it on the viewer's scope so legacy
139|        // cross-unit links stop rendering their todo here. `setRelation()`
140|        // rather than a plain assignment: see the inbox for why.
141|        $ticket->setRelation('task', $this->taskIfInScope($ticket->task_id, $accessibleIds));
142|
143|        $this->showingTicket = $ticket;
144|        $this->showModal = true;
145|    }
146|
147|    /**
148|     * The ticket's task, or null when it is outside the viewer's scope.
149|     *
150|     * @param  array<int>  $accessibleIds
151|     */
152|    private function taskIfInScope(?int $taskId, array $accessibleIds): ?Todo
153|    {
154|        if (! $taskId) {
155|            return null;
156|        }
157|
158|        return Todo::query()
159|            ->whereKey($taskId)
160|            ->where(fn ($q) => $q->whereIn('unit_id', $accessibleIds)
161|                ->orWhere(fn ($q) => $q->whereNull('unit_id')->where('user_id', Auth::id())))
162|            ->first();
163|    }
164|
165|    public function closeDetail(): void
166|    {
167|        $this->showModal = false;
168|        $this->showingTicket = null;
169|    }
170|};
171|?>
