3|namespace App\Http\Controllers\Api;
4|
5|use App\Http\Controllers\Controller;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Models\Person;
8|use App\Models\Unit;
9|use App\Traits\PersianNormalizer;
10|use Illuminate\Http\JsonResponse;
11|use Illuminate\Support\Facades\Cache;
12|use Illuminate\Support\Facades\DB;
13|
14|/**
15| * HR aggregate stats — extracted from HrController.
16| */
17|class HrStatsController extends Controller
18|{
19|    use PersianNormalizer;
20|
21|    /**
22|     * GET /api/hr/stats — aggregated HR stats.
23|     */
24|    public function stats(UnitScopedRequest $request): JsonResponse
25|    {
26|        $accessibleIds = $request->accessibleIds();
27|
28|        $data = Cache::remember(
29|            $this->hrStatsCacheKey($accessibleIds),
30|            now()->addMinutes(5),
31|            function () use ($accessibleIds) {
32|                $idArray = '{'.implode(',', array_map('intval', $accessibleIds)).'}';
33|
34|                $row = DB::selectOne(
35|                    "SELECT
36|                        (SELECT count(*) FROM persons WHERE u_id = ANY(?)) AS total,
37|                        (SELECT coalesce(jsonb_object_agg(coalesce(x.name, x.u_id::text), x.c), '{}')
38|                           FROM (SELECT p.u_id, u.name, count(*) AS c
39|                                 FROM persons p LEFT JOIN units u ON p.u_id = u.id
40|                                 WHERE p.u_id = ANY(?) GROUP BY p.u_id, u.name) x) AS by_unit,
41|                        (SELECT coalesce(jsonb_object_agg(coalesce(x.name, x.s_id::text), x.c), '{}')
42|                           FROM (SELECT p.s_id, s.name, count(*) AS c
43|                                 FROM persons p LEFT JOIN semats s ON p.s_id = s.id
44|                                 WHERE p.s_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.s_id, s.name) x) AS by_semat,
45|                        (SELECT coalesce(jsonb_object_agg(coalesce(x.name, x.t_id::text), x.c), '{}')
46|                           FROM (SELECT p.t_id, t.name, count(*) AS c
47|                                 FROM persons p LEFT JOIN tahsils t ON p.t_id = t.id
48|                                 WHERE p.t_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.t_id, t.name) x) AS by_tahsil,
49|                        (SELECT coalesce(jsonb_object_agg(coalesce(x.name, x.e_id::text), x.c), '{}')
50|                           FROM (SELECT p.e_id, e.name, count(*) AS c
51|                                 FROM persons p LEFT JOIN estekhdams e ON p.e_id = e.id
52|                                 WHERE p.e_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.e_id, e.name) x) AS by_estekhdam,
53|                        (SELECT coalesce(jsonb_object_agg(coalesce(x.name, x.r_id::text), x.c), '{}')
54|                           FROM (SELECT p.r_id, r.name, count(*) AS c
55|                                 FROM persons p LEFT JOIN radifs r ON p.r_id = r.id
56|                                 WHERE p.r_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.r_id, r.name) x) AS by_radif",
57|                    [$idArray, $idArray, $idArray, $idArray, $idArray, $idArray]
58|                );
59|
60|                return [
61|                    'total_personnel' => (int) $row->total,
62|                    'by_unit' => json_decode($row->by_unit, true) ?? [],
63|                    'by_semat' => json_decode($row->by_semat, true) ?? [],
64|                    'by_tahsil' => json_decode($row->by_tahsil, true) ?? [],
65|                    'by_estekhdam' => json_decode($row->by_estekhdam, true) ?? [],
66|                    'by_radif' => json_decode($row->by_radif, true) ?? [],
67|                ];
68|            }
69|        );
70|
71|        return response()->json(['data' => $data]);
72|    }
73|
74|    /**
75|     * GET /api/hr/vacancies — units with no assigned semat holders.
76|     */
77|    public function vacancies(UnitScopedRequest $request): JsonResponse
78|    {
79|        $accessibleIds = $request->accessibleIds();
80|
81|        $scopeHash = md5(implode(',', $accessibleIds));
82|        $version = Cache::get('hr_stats_version', 0);
83|        $cacheKey = "hr:vacancies:v{$version}:{$scopeHash}";
84|
85|        $units = Cache::remember($cacheKey, now()->addMinutes(10), function () use ($accessibleIds) {
86|            return Unit::whereIn('id', $accessibleIds)
87|                ->whereDoesntHave('person')
88|                ->get();
89|        });
90|
91|        return response()->json([
92|            'data' => $units->map(fn ($u) => [
93|                'id' => $u->id,
94|                'name' => $u->name,
95|                'parent_id' => $u->parent_id,
96|            ]),
97|            'meta' => ['total' => $units->count()],
98|        ]);
99|    }
100|
101|    /**
102|     * GET /api/hr/personnel — paginated personnel list with filters.
103|     */
104|    public function personnel(UnitScopedRequest $request): JsonResponse
105|    {
106|        $accessibleIds = $request->accessibleIds();
107|
108|        $query = Person::leftJoin('units', 'persons.u_id', '=', 'units.id')
109|            ->leftJoin('semats', 'persons.s_id', '=', 'semats.id')
110|            ->leftJoin('tahsils', 'persons.t_id', '=', 'tahsils.id')
111|            ->leftJoin('estekhdams', 'persons.e_id', '=', 'estekhdams.id')
112|            ->leftJoin('radifs', 'persons.r_id', '=', 'radifs.id')
113|            ->whereIn('persons.u_id', $accessibleIds)
114|            ->select(
115|                'persons.*',
116|                'units.name as unit_name',
117|                'semats.name as semat_name',
118|                'tahsils.name as tahsil_name',
119|                'estekhdams.name as estekhdam_name',
120|                'radifs.name as radif_name',
121|            );
122|
123|        $p = 'persons.';
124|        if ($request->filled('search')) {
125|            $s = self::normalizeForQuery($request->search);
126|            $query->where(function ($q) use ($s, $p) {
127|                $q->where($p.'n_code', 'LIKE', "%{$s}%")
