15|
16|return new class extends Component
17|{
18|    use WithPagination;
19|
20|    public string $reportType = 'tickets';
21|
22|    public ?string $dateFrom = null;
23|
24|    public ?string $dateTo = null;
25|
26|    public ?int $unitId = null;
27|
28|    public ?int $parentUnitId = null;
29|
30|    public ?int $rootUnitId = null;
31|
32|    public string $statusFilter = 'all';
33|
34|    public $units = [];
35|
36|    /** Issue #819 — see the dashboard's `emptyScope` banner for the rationale. */
37|    public bool $emptyScope = false;
38|
39|    public function mount(): void
40|    {
41|        $this->dateFrom = Jalalian::fromCarbon(now()->subDays(30))->format('Y/m/d');
42|        $this->dateTo = Jalalian::fromCarbon(now())->format('Y/m/d');
43|
44|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
45|        $this->emptyScope = $accessibleIds === [];
46|        if ($accessibleIds === []) {
47|            $this->units = [];
48|        } else {
49|            $cacheKey = 'advanced_report:units:'.md5(implode(',', $accessibleIds));
50|            $this->units = Cache::remember($cacheKey, 300, function () use ($accessibleIds) {
51|                return Unit::whereIn('id', $accessibleIds)
52|                    ->select('id', 'name', 'parent_id')
53|                    ->orderBy('name')
54|                    ->get()
55|                    ->toArray();
56|            });
57|        }
58|    }
59|
60|    private function parseJalaliDate(?string $date, bool $endOfDay = false): ?Carbon
61|    {
62|        if (empty($date)) {
63|            return null;
64|        }
65|
66|        try {
67|            $carbon = Jalalian::fromFormat('Y/m/d', $date)->toCarbon();
68|
69|            return $endOfDay ? $carbon->endOfDay() : $carbon->startOfDay();
70|        } catch (\Throwable) {
71|            return null;
72|        }
73|    }
74|
75|    /**
76|     * The chosen from..to range as Carbon bounds, or null when either end is
77|     * missing/invalid or the range is inverted — in which case the daily series
78|     * has no window to fill.
79|     *
80|     * @return array{0: Carbon, 1: Carbon}|null
81|     */
82|    private function dateRange(): ?array
83|    {
84|        $from = $this->parseJalaliDate($this->dateFrom);
85|        $to = $this->parseJalaliDate($this->dateTo, endOfDay: true);
86|
87|        if (! $from || ! $to || $from->gt($to)) {
88|            return null;
89|        }
90|
91|        return [$from, $to];
92|    }
93|
94|    #[Livewire\Attributes\Computed]
95|    public function childUnits()
96|    {
97|        if (! $this->rootUnitId || empty($this->units)) {
98|            return collect();
99|        }
100|
101|        return collect($this->units)->where('parent_id', $this->rootUnitId)->values();
102|    }
103|
104|    #[Livewire\Attributes\Computed]
105|    public function grandChildUnits()
106|    {
107|        if (! $this->parentUnitId || empty($this->units)) {
108|            return collect();
109|        }
110|
111|        return collect($this->units)->where('parent_id', $this->parentUnitId)->values();
112|    }
113|
114|    public function updatedRootUnitId(): void
115|    {
116|        $this->parentUnitId = null;
117|        $this->unitId = null;
118|    }
119|
120|    public function updatedParentUnitId(): void
121|    {
122|        $this->unitId = null;
123|    }
