125|    #[Livewire\Attributes\Computed]
126|    public function reportData(): array
127|    {
128|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
129|
130|        $query = match ($this->reportType) {
131|            'tickets' => Ticket::whereIn('unit_id', $accessibleIds),
132|            'todos' => Todo::whereIn('unit_id', $accessibleIds),
133|            'persons' => Person::whereIn('u_id', $accessibleIds),
134|            default => Ticket::whereIn('unit_id', $accessibleIds),
135|        };
136|
137|        // فیلتر تاریخ (ورودی شمسی)
138|        if ($from = $this->parseJalaliDate($this->dateFrom)) {
139|            $query->where('created_at', '>=', $from);
140|        }
141|        if ($to = $this->parseJalaliDate($this->dateTo, endOfDay: true)) {
142|            $query->where('created_at', '<=', $to);
143|        }
144|
145|        // فیلتر واحد (سلسله‌مراتبی)
146|        $unitId = $this->unitId ?? $this->parentUnitId ?? $this->rootUnitId;
147|        if ($unitId) {
148|            $descendantIds = Unit::descendantIds($unitId)->toArray();
149|            $descendantIds[] = $unitId;
150|            $unitColumn = $this->reportType === 'persons' ? 'u_id' : 'unit_id';
151|            $query->whereIn($unitColumn, $descendantIds);
152|        }
153|
154|        // فیلتر وضعیت
155|        if ($this->statusFilter !== 'all' && $this->reportType !== 'persons') {
156|            $query->where('status', $this->statusFilter);
157|        }
158|
159|        $total = $query->count();
160|
161|        // Issue #736: materialise every day in the chosen range, zeros included,
162|        // so a day with no rows is a zero rather than a missing column. The
163|        // filtered $query is reused, so unit/status/date filters still apply.
164|        $range = $this->dateRange();
165|        $byDay = $range
166|            ? array_map(
167|                fn (array $row) => [
168|                    'day' => Jalalian::fromCarbon(Carbon::parse($row['day']))->format('Y/m/d'),
169|                    'count' => $row['count'],
170|                ],
171|                DailySeries::between($range[0], $range[1])->counts($query->clone(), 'created_at')
172|            )
173|            : [];
174|
175|        $unitColumn = $this->reportType === 'persons' ? 'u_id' : 'unit_id';
176|        $byUnit = $query->clone()
177|            ->selectRaw("$unitColumn, count(*) as count")
178|            ->groupBy($unitColumn)
179|            ->with('unit:id,name')
180|            ->get()
181|            ->mapWithKeys(fn ($item) => [$item->unit?->name ?? 'نامشخص' => $item->count])
182|            ->toArray();
183|
184|        $details = [];
185|        if ($this->reportType === 'tickets') {
186|            $details = [
187|                'urgent' => (clone $query)->where('priority', 'urgent')->count(),
188|                'normal' => (clone $query)->where('priority', 'normal')->count(),
189|                'low' => (clone $query)->where('priority', 'low')->count(),
190|                'overdue' => (clone $query)
191|                    ->whereIn('status', ['created', 'forwarded'])
192|                    ->where('deadline', '<', now())
193|                    ->count(),
194|            ];
195|        } elseif ($this->reportType === 'persons') {
196|            $details = [
197|                'byEstekhdam' => Person::selectRaw('COALESCE(estekhdams.name, ?) as name, COUNT(*) as count', ['نامشخص'])
198|                    ->leftJoin('estekhdams', 'persons.e_id', '=', 'estekhdams.id')
199|                    ->whereIn('persons.u_id', $accessibleIds)
200|                    ->when($unitId, fn ($q) => $q->whereIn('persons.u_id', $descendantIds))
201|                    ->groupBy('name')
202|                    ->pluck('count', 'name')
203|                    ->toArray(),
204|                'byTahsil' => Person::selectRaw('COALESCE(tahsils.name, ?) as name, COUNT(*) as count', ['نامشخص'])
205|                    ->leftJoin('tahsils', 'persons.t_id', '=', 'tahsils.id')
206|                    ->whereIn('persons.u_id', $accessibleIds)
207|                    ->when($unitId, fn ($q) => $q->whereIn('persons.u_id', $descendantIds))
208|                    ->groupBy('name')
209|                    ->pluck('count', 'name')
210|                    ->toArray(),
211|                'bySemat' => Person::selectRaw('COALESCE(semats.name, ?) as name, COUNT(*) as count', ['نامشخص'])
212|                    ->leftJoin('semats', 'persons.s_id', '=', 'semats.id')
213|                    ->whereIn('persons.u_id', $accessibleIds)
214|                    ->when($unitId, fn ($q) => $q->whereIn('persons.u_id', $descendantIds))
215|                    ->groupBy('name')
216|                    ->pluck('count', 'name')
217|                    ->toArray(),
218|            ];
219|        }
220|
221|        return [
222|            'total' => $total,
223|            'byDay' => $byDay,
224|            'byUnit' => $byUnit,
225|            'details' => $details,
226|        ];
227|    }
228|
229|    /**
230|     * Fresh chart data for JS (wire:navigate + filter updates).
231|     *
232|     * @return array{total: int, byDay: array, byUnit: array, details: array}
233|     */
234|    public function chartPayload(): array
235|    {
236|        return $this->reportData;
237|    }
