32|    {
33|        $v = Cache::get('maps_version', 0);
34|        $this->regions = Cache::remember('unit_map:regions:v' . $v, 300, function () {
35|            return Region::where('type', 'county')
36|                ->select('id', 'name')
37|                ->get()
38|                ->toArray();
39|        });
40|
41|        $this->centerTypes = Cache::remember('unit_map:center_types:v' . $v, 300, function () {
42|            return UnitType::whereIn('id', [5, 6, 7])
43|                ->select('id', 'name')
44|                ->get()
45|                ->toArray();
46|        });
47|
48|        $this->subTypes = [
49|            ['name' => 'خانه بهداشت'],
50|            ['name' => 'پایگاه'],
51|            ['name' => 'قمر'],
52|        ];
53|    }
54|
55|    public function updatedSelectedRegions(): void
56|    {
57|        $this->showSelectedCounties();
58|        $this->loadUnits();
59|    }
60|
61|    private function showSelectedCounties(): void
62|    {
63|        if (empty($this->selectedRegions)) {
64|            $this->dispatch('county-boundaries-loaded', counties: []);
65|            return;
66|        }
67|
68|        $cacheKey = 'county_boundaries_v' . Cache::get('maps_version', 0) . '_' . md5(implode(',', $this->selectedRegions));
69|
70|        $counties = Cache::remember($cacheKey, 300, function () {
71|            return Region::whereIn('id', $this->selectedRegions)
72|                ->whereNotNull('boundary_id')
73|                ->with('boundary')
74|                ->get()
75|                ->map(fn($r) => [
76|                    'id' => $r->id,
77|                    'name' => $r->name,
78|                    'geojson' => $r->boundary?->geojson,
79|                ])
80|                ->filter(fn($r) => $r['geojson'])
81|                ->values()
82|                ->toArray();
83|        });
84|
85|        $this->dispatch('county-boundaries-loaded', counties: $counties);
86|    }
87|
88|    public function updatedSelectedSubTypes(): void
89|    {
90|        $this->loadUnits();
91|    }
92|
93|    public function updatedSelectedCenterTypes(): void
94|    {
95|        $this->loadUnits();
96|    }
97|
98|    public function loadUnits(): void
99|    {
100|        if (empty($this->selectedRegions)) {
101|            $this->units = [];
102|            $this->dispatch('units-updated', units: []);
103|            return;
104|        }
105|
106|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
107|
108|        // Collect query results first, then combine — avoids merge()/map()
109|        // on an empty untyped collect() (Collection<NEVER,NEVER>).
110|        $unitLists = [];
111|
112|        // Centers (types 5, 6, 7) — filtered by selected center types
113|        $parentIds = collect();
114|        if (!empty($this->selectedCenterTypes)) {
115|            $centers = Unit::whereIn('id', $accessibleIds)  // Organizational Scope
116|                ->whereNotNull('boundary_id')
117|                ->whereIn('region_id', $this->selectedRegions)
118|                ->whereIn('unit_type_id', $this->selectedCenterTypes)
119|                ->select('id', 'name', 'unit_type_id', 'boundary_id')
120|                ->with('boundary:id,boundary')
121|                ->get();
122|            $unitLists[] = $centers;
123|
124|            // Get IDs of selected centers from the already-loaded collection (in-memory, no extra query)
125|            $parentIds = $centers->pluck('id');
126|        }
127|
128|        // Sub-types (خانه بهداشت, پایگاه, قمر) — only if their parent center type is selected
129|        if (!empty($this->selectedSubTypes) && !empty($this->selectedCenterTypes)) {
130|            $subTypeIds = $this->resolveSubTypeIds();
131|
132|            $unitLists[] = Unit::whereIn('id', $accessibleIds)  // Organizational Scope
133|                ->whereNotNull('boundary_id')
134|                ->whereIn('region_id', $this->selectedRegions)
135|                ->whereIn('unit_type_id', $subTypeIds)
136|                ->whereIn('parent_id', $parentIds)
137|                ->select('id', 'name', 'unit_type_id', 'boundary_id')
138|                ->with('boundary:id,boundary')
139|                ->get();
140|        }
141|
142|        $units = collect($unitLists)->collapse();
143|
144|        $this->units = $units->map(fn($u) => [
145|            'id' => $u->id,
146|            'name' => $u->name,
147|            'type_id' => $u->unit_type_id,
148|            'geojson' => $u->boundary?->geojson,
149|        ])->toArray();
150|
151|        $this->dispatch('units-updated', units: $this->units);
152|    }
153|
154|    private function resolveSubTypeIds(): array
155|    {
156|        $typeIds = [];
157|        foreach ($this->selectedSubTypes as $name) {
158|            $typeIds = array_merge($typeIds, self::SUB_TYPE_MAP[$name] ?? []);
159|        }
160|        return array_unique($typeIds);
161|    }
162|};
