112|<script>
113|    // وضعیت مشترک را هر کسی که زودتر اجرا شود می‌سازد؛ گیج‌ها ممکن است پیش از
114|    // poller صفحه ساخته شوند، پس ساختن شیء باید در هر دو طرف idempotent باشد.
115|    window.zabbixGauges = window.zabbixGauges || {
116|        values: {}, error: null, loading: false, loaded: false, subscribers: [], timer: null,
117|    };
118|
119|    // تعریف تابع در window برای دسترسی سراسری
120|    window.signalGauge = function(signalItemId, frequencyItemId, responseTimeItemId, min, max, unit, frequencyUnit, responseTimeUnit, title) {
121|        return {
122|            signalItemId,
123|            frequencyItemId,
124|            responseTimeItemId,
125|            min, max, unit, frequencyUnit, responseTimeUnit, title,
126|            signal: null,
127|            frequency: null,
128|            responseTime: null,
129|            loading: false,
130|            error: null,
131|            circumference: 2 * Math.PI * 45,
132|            bound: null,
133|
134|            init() {
135|                const state = window.zabbixGauges;
136|                this.bound = this.apply.bind(this);
137|                state.subscribers.push(this.bound);
138|                this.apply();
139|            },
140|
141|            /** مقادیر را از وضعیت مشترک می‌خواند؛ تنها جایی که به داده وصل می‌شود. */
142|            apply() {
143|                const state = window.zabbixGauges;
144|                const values = state.values || {};
145|
146|                this.loading = state.loading;
147|                this.signal = values[this.signalItemId] ?? null;
148|                this.frequency = values[this.frequencyItemId] ?? null;
149|                this.responseTime = values[this.responseTimeItemId] ?? null;
150|
151|                this.error = state.error;
152|
153|                // تا وقتی اولین fetch تمام نشده «داده‌ای یافت نشد» زودهنگام است؛
154|                // قبلاً در این حالت فقط «—» نشان داده می‌شد.
155|                if (!this.error && state.loaded &&
156|                    this.signal === null && this.frequency === null && this.responseTime === null) {
157|                    this.error = 'داده‌ای یافت نشد';
158|                }
159|            },
160|
161|            get displaySignal() {
162|                return this.signal !== null ? this.signal.toFixed(1) : '—';
163|            },
164|
165|            get displayFrequency() {
166|                return this.frequency !== null ? this.frequency.toFixed(1) : '—';
167|            },
168|
169|            get displayResponseTime() {
170|                if (this.responseTime === null) return '—';
171|                const ms = this.responseTime * 1000;
172|                return ms >= 1 ? Math.round(ms) : ms.toFixed(1);
173|            },
174|
175|            get responseTimeColorClass() {
176|                if (this.responseTime === null) return 'text-base-content';
177|                const ms = this.responseTime * 1000;
178|                if (ms < 3) return 'text-success';
179|                if (ms >= 3 && ms <= 7) return 'text-warning';
180|                return 'text-error';
181|            },
182|
183|            get dashOffset() {
184|                if (this.signal === null) return this.circumference;
185|                const percent = Math.min(100, Math.max(0, ((this.signal - this.min) / (this.max - this.min)) * 100));
186|                return this.circumference - (percent / 100) * this.circumference;
187|            },
188|
189|            destroy() {
190|                const state = window.zabbixGauges;
191|                if (!state || !this.bound) return;
192|                const at = state.subscribers.indexOf(this.bound);
193|                if (at !== -1) state.subscribers.splice(at, 1);
194|            }
195|        };
196|    };
197|</script>
