3|use App\Services\AccessService;
4|use App\Services\UnitTreeService;
5|use Livewire\Component;
6|
7|/**
8| * Reusable unit tree (issue #704 — Plan 30).
9| *
10| * ============================ REUSE CONTRACT ============================
11| * Owns ONLY tree mechanics: scope-rooted roots, lazy children, expanded
12| * state, search, and expand/collapse-all. It knows nothing about any
13| * particular kind of data.
14| *
15| * IN  (props):
16| *   badgeView        string|null  Blade view rendered per node; receives
17| *                               $unit and $badgeData. Omit for a bare tree.
18| *   badgeData        array        Opaque per-unit payload (unit-id => data)
19| *                               forwarded verbatim to badgeView. The tree
20| *                               never interprets it.
21| *   searchPlaceholder string      Search input placeholder.
22| *
23| * OUT (events):
24| *   unit-selected    int          Fired on node click. The parent page listens
25| *                               and fills its own detail panel — the tree
26| *                               deliberately does not know what "selected"
27| *                               means for the page embedding it. The listener
28| *                               MUST re-check the id against its own
29| *                               accessibleUnitIds(): selectNode is a public
30| *                               Livewire method and forwards ANY id (pinned
31| *                               by UnitTreeLivewireTest).
32| *
33| * A new feature (e.g. covered population per unit) needs ZERO tree code:
34| *
35| *     <livewire:unit.tree badge-view="livewire.population.coverage-badge" />
36| *
37| * plus a badge view and a `#[On('unit-selected')]` listener. Resist adding
38| * further knobs until a second real consumer needs one.
39| * =======================================================================
40| */
41|return new class extends Component
42|{
43|    /** Levels open on first paint; deeper levels lazy-load on expand. */
44|    private const INITIAL_EXPAND_LEVELS = 3;
45|
46|    /** Blade view rendered per node; receives $unit + $badgeData. */
47|    public ?string $badgeView = null;
48|
49|    /**
50|     * Opaque per-unit payload forwarded verbatim to the badge view — the tree
51|     * does not know or care what it holds (counts, flags, anything keyed by
52|     * unit id).
53|     *
54|     * @var array<int, mixed>
55|     */
56|    public array $badgeData = [];
57|
58|    /** Search input placeholder. */
59|    public string $searchPlaceholder = 'جستجوی واحد...';
60|
61|    /**
62|     * Unit IDs expanded in the tree, as strings (wire:click payloads are strings).
63|     *
64|     * @var array<int, string>
65|     */
66|    public array $expanded = [];
67|
68|    public string $search = '';
69|
70|    /**
71|     * Units matched by the current search (id => true). Nodes highlight from
72|     * THIS set instead of re-deriving a match against the raw term, so the
73|     * highlight and the search can never disagree about what matched.
74|     *
75|     * @var array<int, bool>
76|     */
77|    public array $matchIds = [];
78|
79|    /**
80|     * Scope ids for the current request — resolved once, then memoized.
81|     *
82|     * @var array<int>|null
83|     */
84|    protected ?array $accessibleIds = null;
85|
86|    /**
87|     * Scope-rooted top of the tree.
88|     *
89|     * @var \Illuminate\Support\Collection<int, \App\Models\Unit>
90|     */
91|    public $rootUnits;
92|
93|    /**
94|     * Lazily loaded children, keyed by parent unit ID.
95|     *
96|     * @var array<int, \Illuminate\Support\Collection<int, \App\Models\Unit>>
97|     */
98|    public array $lazyChildren = [];
99|
100|    public function mount(): void
101|    {
102|        $this->loadData();
103|    }
104|
105|    /**
106|     * The caller's accessible unit ids, resolved once per request so node
107|     * templates and recursive helpers never re-enter the container.
108|     *
109|     * @return array<int>
110|     */
111|    public function accessibleIds(): array
112|    {
113|        if ($this->accessibleIds === null) {
114|            $this->accessibleIds = app(AccessService::class)->accessibleUnitIds();
115|        }
116|
117|        return $this->accessibleIds;
118|    }
119|
120|    /**
121|     * Load the scope-rooted top of the tree, then open the first N levels.
122|     */
123|    public function loadData(): void
124|    {
125|        $accessibleIds = $this->accessibleIds();
126|
127|        $this->rootUnits = app(UnitTreeService::class)->roots($accessibleIds);
128|
129|        if ($this->expanded === []) {
130|            $this->expanded = $this->expandFirstNLevels($this->rootUnits, self::INITIAL_EXPAND_LEVELS);
131|        }
132|
133|        $this->loadExpandedChildren();
134|    }
135|
136|    /**
137|     * Expand up to maxLevel, loading children one LEVEL at a time.
138|     *
139|     * Each iteration collects the current level's ids and fetches their
140|     * children with a SINGLE `childrenOfMany()` call (issue #722) — the
141|     * recursion this replaced issued one `childrenOf()` per node, so a
142|     * 1→6→36 tree spent ~44 queries just to paint. Units with no children
143|     * get an EMPTY collection cached too, so the view renders them as leaves
144|     * without re-asking `hasChildren()` on every repaint.
145|     *
146|     * Deliberate behavior note: `$expanded` comes back in LEVEL order here,
147|     * not the old depth-first order. Every consumer is membership-only
148|     * (`in_array` in tree-node.blade.php, `in_array`/`array_diff` in
149|     * `toggle()`), so the order is unobservable.
150|     *
151|     * @param  iterable<mixed, \App\Models\Unit>  $nodes
152|     * @return array<int, string>
153|     */
154|    protected function expandFirstNLevels($nodes, int $maxLevel): array
155|    {
156|        $ids = [];
157|        $accessibleIds = $this->accessibleIds();
158|        $service = app(UnitTreeService::class);
159|        $level = collect($nodes);
160|
161|        for ($depth = 1; $level->isNotEmpty() && $depth <= $maxLevel; $depth++) {
162|            $levelIds = [];
163|
164|            foreach ($level as $node) {
165|                $ids[] = (string) $node->id;
166|                $levelIds[] = (int) $node->id;
167|            }
168|
169|            // The deepest level that is OPENED is not descended into: its own
170|            // children stay lazy until the user toggles it (loadExpandedChildren
171|            // backfills them for the initial paint).
172|            if ($depth === $maxLevel) {
173|                break;
174|            }
175|
176|            $grouped = $service->childrenOfMany($levelIds, $accessibleIds);
177|
178|            foreach ($levelIds as $id) {
179|                $this->lazyChildren[$id] = $grouped->get($id, collect());
180|            }
181|
182|            $level = $grouped->flatten();
183|        }
184|
185|        return $ids;
186|    }
187|
188|    /**
189|     * Load children for every expanded unit not yet in the lazy cache — ONE
190|     * batched query for all of them instead of one per node (issue #722).
191|     */
192|    public function loadExpandedChildren(): void
193|    {
194|        $missing = [];
195|
196|        foreach ($this->expanded as $unitId) {
197|            $id = (int) $unitId;
198|
199|            if (! isset($this->lazyChildren[$id])) {
200|                $missing[] = $id;
201|            }
202|        }
203|
204|        if ($missing === []) {
205|            return;
206|        }
207|
208|        $grouped = app(UnitTreeService::class)->childrenOfMany($missing, $this->accessibleIds());
209|
210|        // Childless units are cached as EMPTY collections, so a repaint never
211|        // repeats the query for them.
212|        foreach ($missing as $id) {
213|            $this->lazyChildren[$id] = $grouped->get($id, collect());
214|        }
215|    }
216|
217|    /**
218|     * Lazy-load the children of one unit. Out-of-scope units are ignored.
219|     */
220|    public function loadChildren(int $unitId): void
221|    {
222|        $accessibleIds = $this->accessibleIds();
223|
224|        if (! in_array($unitId, $accessibleIds, true)) {
225|            return;
226|        }
227|
228|        if (! isset($this->lazyChildren[$unitId])) {
229|            $this->lazyChildren[$unitId] = app(UnitTreeService::class)->childrenOf($unitId, $accessibleIds);
230|        }
231|    }
232|
233|    /**
234|     * A node was clicked. Hand the id to the embedding page and let it decide
235|     * what to show — the tree has no opinion about the payload.
236|     */
237|    public function selectNode(int $id): void
238|    {
239|        $this->dispatch('unit-selected', unitId: $id);
240|    }
241|
242|    /**
243|     * @param  int|string  $id  Unit id; wire:click delivers it unquoted, so both shapes arrive.
244|     */
245|    public function toggle($id): void
246|    {
247|        $id = (string) $id;
248|
249|        if (in_array($id, $this->expanded, true)) {
250|            $this->expanded = array_values(array_diff($this->expanded, [$id]));
251|        } else {
252|            $this->expanded[] = $id;
253|            $this->loadChildren((int) $id);
254|        }
255|    }
256|
257|    /**
258|     * Open every unit in scope: walk the hierarchy from the roots, loading
259|     * children as we go so the very next paint is already complete. (The old
260|     * org chart collected only the root ids here — "باز کردن همه" restored a
261|     * single level, which is not what the label promises.)
262|     */
263|    public function expandAll(): void
264|    {
265|        $accessibleIds = $this->accessibleIds();
266|        $this->expanded = array_values(array_unique(
267|            $this->collectAllIds($this->rootUnits, $accessibleIds, [])
268|        ));
269|        $this->loadExpandedChildren();
270|    }
271|
272|    public function collapseAll(): void
273|    {
274|        $this->expanded = [];
275|        $this->lazyChildren = [];
276|    }
277|
278|    /**
279|     * Reset the tree, then reveal every match together with its ancestor chain
280|     * so a deep hit is never hidden behind a collapsed branch.
281|     */
282|    public function updatedSearch(): void
283|    {
284|        $this->expanded = [];
285|        $this->lazyChildren = [];
286|        $this->matchIds = [];
287|
288|        $accessibleIds = $this->accessibleIds();
289|        $matches = app(UnitTreeService::class)->search($this->search, $accessibleIds);
290|
291|        if ($matches->isEmpty()) {
292|            return;
293|        }
294|
295|        foreach ($matches as $matched) {
296|            $this->matchIds[(int) $matched->id] = true;
297|        }
298|
299|        $tree = app(UnitTreeService::class);
