23|    /**
24|     * Apply bbox spatial filter using lat/lng columns (works without geom column).
25|     */
26|    protected function applyBbox($query, UnitScopedRequest $request)
27|    {
28|        if (! $request->filled('bbox')) {
29|            return $query;
30|        }
31|
32|        $bbox = explode(',', $request->bbox);
33|        if (count($bbox) !== 4) {
34|            return $query;
35|        }
36|
37|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
38|
39|        $query->whereBetween('lat', [$minLat, $maxLat])
40|            ->whereBetween('lng', [$minLon, $maxLon]);
41|
42|        return $query;
43|    }
