69|     * Fixes Issue #456: GIS bbox rounding caused incorrect map data display.
70|     */
71|    protected function normalizedBbox(UnitScopedRequest $request): string
72|    {
73|        if (! $request->filled('bbox')) {
74|            return 'all';
75|        }
76|
77|        $bbox = explode(',', $request->bbox);
78|        if (count($bbox) !== 4) {
79|            return 'all';
80|        }
81|
82|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
83|
84|        return implode(',', [
85|            round($minLon, 4),
86|            round($minLat, 4),
