import re, os

root = "/home/runner/h-dashboard/resources/views"
pat = re.compile(r'\$\w+->(\w+)(->\w+)*\?->(name|id|title|label)|\$(unit|user|person|ticket|todo|comment|log|device|audit|role|activity|child|parent)(->\w+)?->(unit|person|user|unitType|semat|tahsil|estekhdam|radif|region|parent|task|attachments|comments|children)\b')

out = []
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith('.blade.php'):
            continue
        p = os.path.join(dirpath, fn)
        with open(p, encoding='utf-8', errors='replace') as f:
            for i, line in enumerate(f, 1):
                if '@foreach' in line or '@php' in line or '->map(' in line or '=>' in line:
                    if pat.search(line):
                        out.append(f"{p.replace(root,'')}:{i}: {line.strip()[:200]}")
print("\n".join(out[:120]))
print("TOTAL", len(out))"}

