116|    /**
117|     * Build full tree structure from a flat collection using a single CTE query.
118|     * Replaces the N+1 recursive eager loading pattern (childrenRecursive).
119|     *
120|     * @param  array<int>  $rootIds
121|     * @param  array<int>|null  $accessibleIds  If null, no scope filter applied; an empty array means "in scope of nothing" and intersects to zero rows
122|     * @return Collection<int, static>
123|     */
124|    public static function buildTree(array $rootIds, ?array $accessibleIds = null): Collection
125|    {
126|        if (empty($rootIds)) {
127|            return collect();
128|        }
129|
130|        // Single CTE: fetch all descendants of root units (inclusive)
131|        $allIds = self::descendantIds($rootIds)->all();
132|
133|        if ($accessibleIds !== null) {
134|            $allIds = array_values(array_intersect($allIds, $accessibleIds));
135|        }
136|
137|        if (empty($allIds)) {
138|            return collect();
139|        }
140|
141|        // Single query: load all relevant units with their types
142|        $models = self::query()
143|            ->with('unitType')
144|            ->whereIn('units.id', $allIds)
145|            ->get();
146|
147|        /** @var array<int, static> $allUnits */
148|        $allUnits = [];
149|        /** @var array<int, list<static>> $childrenMap */
150|        $childrenMap = [];
151|        foreach ($models as $unit) {
152|            $allUnits[$unit->id] = $unit;
153|        }
154|
155|        // Build adjacency list
156|        foreach ($allUnits as $unit) {
157|            $parentId = $unit->parent_id;
158|            if ($parentId !== null && isset($allUnits[$parentId])) {
159|                $childrenMap[$parentId][] = $unit;
160|            }
161|        }
162|
163|        // Recursive closure to attach children
164|        $attachChildren = function (Unit $unit) use (&$attachChildren, $childrenMap): void {
165|            $unit->childrenRecursive = collect($childrenMap[$unit->id] ?? []);
166|            foreach ($unit->childrenRecursive as $child) {
167|                $attachChildren($child);
168|            }
169|        };
170|
171|        // Build root collection
172|        $roots = collect();
173|        foreach ($rootIds as $rootId) {
174|            if (isset($allUnits[$rootId])) {
175|                $roots[] = $allUnits[$rootId];
176|            }
177|        }
178|
179|        foreach ($roots as $root) {
180|            $attachChildren($root);
181|        }
182|
183|        return $roots;
184|    }
